INSERT INTO `cdb_posts` VALUES (54, 73, 32, 0, '', '六月飞雪', '', 1070525040, '好吧，我想下午三四点的时候气氛会好点（特别是傍晚），我会带上U2灯，自己在用的反光板有点小。模特你约，两套衣服就行，素色点和艳丽点的。周六或周日时间你来定（最好能在周日），我解决一辆小车。另，能不能先看钱湖韩岭老街再到跑马场？', '61.130.101.46', 1, 0, 0, 0, 0, 0);
