INSERT INTO `cdb_posts` VALUES (55, 74, 42, 0, '', '飘', '照片是用什么软件进行后期处理的。？', 1070529660, '初来乍到想请问各位大侠，照片的后期制作是用什么软件处理的 难道仅仅只是用的。photoshop吗？可很有瑞丽封面的味道。\r\n还有还有，就是欧洲游记是用什么进行后期制作的呢？', '210.51.244.162', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (55, 74, 43, 0, '', 'adan', '', 1070529840, 'HOHO~一般来说PHOTOSHOP在后期处理中占的比例比较大~当然还有一些其他的辅助软件来帮助处理~：）\r\n欧洲游记完全是由PHOTOSHOP来后期处理完成的~HOHO', '221.136.138.193', 1, 0, 0, 0, 0, 0);
