INSERT INTO `cdb_posts` VALUES (53, 12, 59, 0, '', 'adan', '', 1067256840, '嘿嘿~~LOGO上不是有中文吗~逸憩摄影\r\n第一层含义就是一起摄影的谐音~\r\n第二层比较深奥一点点~~逸就是安逸，憩就是休憩~\r\n也就是舒舒服服摄影的意思啊~HOHO~\r\n\r\n我们的这个网站是供大家互相交流摄影心得，提供摄影相关信息的~\r\n同时我们还有电子相册~网站会在这个星期推出来~大家稍微等两天~免费注册~免费相册哦~哈哈~\r\n\r\n希望大家多多支持我们~：）', '221.136.187.138', 1, 0, 0, 0, 0, 0);
