INSERT INTO `cdb_posts` VALUES (50, 41, 263, 0, '', '六月飞雪', '', 1069723440, '尹兄，多日不见，过得可好。恭喜鸟枪换成大炮了，不过，有空多练练举重呀。这家伙拍风景没得说，就是沉，长途旅行的最大负担。有添数码的了么？我还在胶卷堆里苦苦挣扎来着。对了，你的号码1305678****还在用么？', '61.130.101.46', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (49, 48, 264, 0, '', 'vivienne', '', 1069735080, '[quote][b]以下是引用[i]六月飞雪在2003-11-24 15:37:11[/i]的发言：[/b]\r\n个人认为，买脚架与音响颇为相通。选择音响线的价格是音响总价的10%-20%。贵点也无妨么，一次投资，终生受用么\r\n[/quote]有道理！不知道自己背着6斤重的东西，跑不跑得了远路。', '221.136.136.15', 1, 0, 0, 0, 0, 0);
