INSERT INTO `cdb_posts` VALUES (54, 56, 312, 0, '', 'admin', '活动花絮~2', 1069859040, '开色拉~~大家开始抄家伙~先拍点风景热热身~HOHO\r\n[img]/bbs/UploadFile/20031126225637.jpg[/img]\r\n\r\n\r\n\r\n\r\n正式开工~~且看MM是怎样被色狼“练”出来的~\r\n[img]/bbs/UploadFile/20031126225739.jpg[/img]\r\n\r\n\r\n\r\n\r\n小辫子：为人民服务\r\n[img]/bbs/UploadFile/20031126225918.jpg[/img]\r\n\r\n\r\n\r\nMM：这下面圆巴拉叽的什么东东啊~\r\n色狼：别动~要拍拉\r\n[img]/bbs/UploadFile/200311262300.jpg[/img]\r\n\r\n\r\n\r\n\r\n瞧把咱一只眼GG乐得，不知道看上哪个美女了~HOHO\r\n[img]/bbs/UploadFile/2003112623118.jpg[/img]\r\n\r\n\r\n\r\n\r\n见缝插针~MM化妆也不能放过~宁可错拍一千，不可放过一张~嘿嘿~\r\n[img]/bbs/UploadFile/2003112623220.jpg[/img]\r\n\r\n\r\n\r\n\r\n活动结束~打道回府~MM开道~\r\n[img]/bbs/UploadFile/20031126224626.jpg[/img]\r\n\r\n\r\n\r\n\r\n老僧同学能和MM走在一块儿这可乐坏了~好像在路边捡到半支烟头~HOHO\r\n[img]/bbs/UploadFile/200311262340.jpg[/img]\r\n\r\n\r\n\r\n\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2003-11-26 23:08:53编辑过][/color][/align]\r', '221.136.138.193', 1, 0, 0, 0, 0, 0);
