INSERT INTO `cdb_posts` VALUES (55, 77, 360, 0, '', '月落西山', '关于站点更改的建议！', 1070944200, '站点首页列表最好使用精华的照片，不要上什么就显示什么。这样更能吸引人。而论坛开通上传照片的功能。当论坛的照片达到大家公认后，再由斑竹转到主页上去，这样能提高主页的质量！\r\n\r\n我这么说大家别生气，这里拍pp真的不错的感觉就飘雪等人，我们其他人好象拍好多才能找出一个到两个好的，要是不管什么都往主页上放的话，使得主页质量大大下降！\r\n\r\n个人意见！', '61.179.111.146', 1, 0, 0, 0, 0, 0);
