INSERT INTO `cdb_posts` VALUES (54, 173, 491, 0, '', '睁一只眼', '逸憩摄影会所-4月16日-活动通知。', 1081900380, '时间：4月16日，晚7点半准时\r\n地点：江东百丈路会展中心香辣居右邻“提克休闲酒吧” （以后将作为逸憩摄影活动和办公场地）\r\n活动内容：现场观片，摄友和模特座谈，photoshop处理技巧讲座（主讲:Ccong）。\r\n收费情况：参加活动免费    酒水费用自理\r\n\r\n欢迎各位摄友踊跃参加，谢谢！', '61.174.164.126', 1, 0, 0, 0, 0, 0);
