INSERT INTO `cdb_posts` VALUES (51, 174, 498, 0, '', '光的兴奋', '出售全新的NIKON28~70MM 顶级镜头', 1081914540, '人出售买了3个多月的AF-S NIKKOR 28~70MM 1：2.8D尼康顶级镜头，使用不多完全是全新的，这样的顶级镜头就不要图片了，完全多余\r\n\r\n发票保修单和精美的皮桶一样不少全部都在，并随镜赠送保谷偏正镜一块，渐变灰1块，\r\n\r\n价格电话商量，原价12000大洋（我在杭州可随时回宁波\r\n\r\n本人电话13867479860,请晚上7点以后联系\r\n\r\n', '218.108.191.2', 1, 0, 0, 0, 0, 0);
