INSERT INTO `cdb_posts` VALUES (54, 180, 524, 0, '', 'adan', '周日人像拍摄活动--初夏的午[公告]', 1082515860, '活动时间：本周日下午[4月25日]\r\n活动地点：逸憩会所[会展中心旁的提克酒吧]\r\n活动费用：30元/人[场地费用以及莫特费]\r\n活动人数：10人\r\n\r\n模特：Linda\r\n\r\n[IMG]/pic/adan/03010303.jpg[/IMG]\r\n\r\n\r\n[IMG]/pic/adan/122015.jpg[/IMG]\r\n\r\n\r\n想要参加的色友请跟贴留下联系方法~\r\n\r\n相关注意事项：拍摄模特照片不得用于任何商业用途，当场后先签到交费~谢谢合作\r\n\r\n\r\n\r\n\r', '210.83.124.138', 1, 0, 0, 0, 0, 0);
