INSERT INTO `cdb_posts` VALUES (55, 194, 581, 0, '', '睁一只眼', '', 1084905420, '目前收到三笔来自招商银行的捐助：小黑版主200.01元，小武 200.02元，多年以后 100元\r\n四笔现金捐助：易索网友现金 捐助100元（名字保留）\r\n　　　　　　 小白白/豆腐干/小强 现金捐助 100/100/160元\r\n　　　　　　 ssong 200元\r\n工商银行账户：来自ahui的100元。\r\n合计：1260.03元', '61.175.131.208', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 199, 582, 0, '', '睁一只眼', '5月23日&nbsp;逸憩摄影&nbsp;外拍活动通知', 1084935420, '时间：5月23日星期日  下午12时30分 （如预计雨天则可能提前至周六）\r\n集合地点：江北第三医院附近直达保国寺的公交车站附近（随后我们会进一步通知）\r\n拍摄地点：江北保国寺 及其附近一免费景点\r\n活动内容：特邀模特拍摄\r\n收费方式：景点门票和交通费用自理，活动组织和模特费用共计20元/人，签到时收取\r\n参加人员：资格不限。\r\n\r\n注意事项：请摄友务必准时到达集合地点。\r\n\r\ntips：保国寺门票大概成人20元，我们建议摄友准备一张1吋照片，事先在天一阁南门处花30元办理通票，持该票可以在一年内持卡免费进入天一阁和保国寺等多处收费景区。比较超值。\r\n\r\n咨询电话和联系人：13968334613 尹东岳\r\n\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2004-5-19 11:05:43编辑过][/color][/align]\r', '61.175.131.208', 1, 0, 0, 0, 0, 0);
