INSERT INTO `cdb_posts` VALUES (54, 204, 606, 0, '', '睁一只眼', '会所活动啦！', 1085404800, '活动时间：5月26日（星期三）晚 8点整\r\n活动地点：江东大步街17号 提克酒吧 （江东会展中心大厦B座裙楼 香辣居隔壁）\r\n\r\n活动内容：摄友交流会。片源由网友自由荐稿，要求原创。\r\n\r\n注意事项：1’ 参加活动的摄友务必准时到场，否则会给他人带来不便。\r\n　　　　　2’ 有意展出自己作品的摄友请带数码作品（U盘或者CF卡）\r\n　　　　　　　　　　要求图片大小在800*600像素以上　QQ：205148\r\n　　　　　　　　 （作品交至提克酒吧，即日起每晚都可，也可电话联系13968334613）\r\n\r\n费用：10元/人（酒吧提供茶水或者碳酸饮料一人份）\r\n', '61.153.152.142', 1, 0, 0, 0, 0, 0);
