INSERT INTO `cdb_posts` VALUES (48, 208, 621, 0, '', 'admin', '开通论坛贵宾在摄影技巧板块中的上传图片功能~[公告]', 1086797280, '应众多色友要求现17论坛的摄影技巧板块为本站的贵宾(即资深会员)开通图片上传功能~\r\n要求单个图片大小不得超过500K，一次性可上传图片限制为10幅~\r\n\r\n\r\n网站原来的资深会员在论坛里自动升级为贵宾，普通会员必须在论坛里的经验值超过1000方可申请贵宾身份~申请资料请通过论坛的短信功能发给管理员admin.\r\n\r\n谢谢合作~\r\n\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2004-6-10 0:17:38编辑过][/color][/align]\r', '221.136.134.132', 1, 0, 0, 0, 0, 0);
