INSERT INTO `cdb_posts` VALUES (51, 118, 999, 0, '', '六月飞雪', '出蔓富图308RC云台', 1073896500, '因换云台,故出闲置蔓富图308RC云台,送两块快装板,价格好商量,顶端快装板接触处有使用痕迹,价格好商量,图片来不及拍,就先用别人的了\r\n[IMG]/pic/7FNP2CKAS8AC1/userid4586time20031207134048.jpg[/IMG]\r\n[align=right][color=#000066][此贴子已经被作者于2004-1-12 16:35:39编辑过][/color][/align]\r', '61.130.101.46', 1, 0, 0, 0, 0, 0);
