INSERT INTO `cdb_posts` VALUES (55, 119, 1009, 0, '', 'adan', '我们的网站相册可以上传组图了~', 1074071460, '哈哈~感谢蟹蟹的辛勤劳动~\r\n我们的网站相册上传作品功能已经可以上传组图了~\r\n进入到作品上传页面点击上传作品按钮后，跳转到下一页就可以选择是否继续上传图片~\r\n\r\n我们会继续完善网站的功能~希望大家多多支持哦~哈哈~', '210.83.124.138', 1, 0, 0, 0, 0, 0);
