INSERT INTO `cdb_posts` VALUES (54, 120, 1016, 0, '', 'adan', '2004春季活动预告', 1074213480, '活动一:\r\n准备组织色友西塘(或南浔)人文风情游，时间两天。\r\n\r\n\r\n活动二：\r\n四明山采风外拍活动，时间一天。\r\n\r\n\r\n活动三：\r\n舟山东极岛海岛风情外拍游，时间2天。\r\n\r\n具体活动时间以及详细安排请留意网站通知~也欢迎色友提出其他的好的建议和一些出游这些地方的注意事项！~：）\r\n\r\n', '210.83.124.138', 1, 0, 0, 0, 0, 0);
