INSERT INTO `cdb_posts` VALUES (54, 130, 1050, 0, '', '小薇', '各位我是外滩拍照的红衣服客串，片好凶哦', 1077968760, '有没有好瞄一点的拉，太打击我了拉[em01]', '221.136.207.216', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 130, 1051, 0, '', '一土文武', '', 1077986040, '哈哈～！想起来了！\r\n真是对不住你了啊！－－那帮家伙可能都各自珍藏起来了吧！都舍不得贴啊！\r\n哪像我这么实惠的啊！立马就给你贴出来了是吧！嘻嘻！\r\n凶？不是吧？那叫魅！\r\n如果真凶也要像野蛮女友似的凶！呵呵！\r\n', '218.0.14.161', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 130, 1052, 0, '', '小薇', '', 1078026180, '哎呀，反正看起来就是不顺眼拉，你们就不能给我瞄几张顺眼点的啊，太郁闷了，以后再也不去做什么客串了~', '221.136.205.129', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 130, 1053, 0, '', '一土文武', '', 1078031880, '哈哈！对！做也要做正的是吧！\r\n其实是你刚开始。。。大家都不怎么熟啊！没能好好的沟通啊！\r\n不像心动那可是老熟脸了啊！哈！。。。慢慢来！你有条件！肯定能出好PP的！\r\n期待。。。', '218.74.238.165', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 130, 1054, 0, '', '小薇', '', 1078034340, '你说我只看到这么一张照片，能期待什么拉，哈哈~', '221.136.205.129', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 130, 1055, 0, '', '一土文武', '', 1078040940, '期待你以后能有好的表现啊！\r\n第一次拍你！大家难免有点生疏啊！～呵呵！\r\n馒头会有的！\r\n\r\n就像心动。。。棒棒糖不是有了啊～\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2004-2-29 15:51:33编辑过][/color][/align]\r', '218.0.12.71', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (55, 131, 1056, 0, '', '睁一只眼', '《逸憩摄影》重要通知', 1078047300, '《逸憩摄影》重要通知\r\n\r\n    非常遗憾的通知大家，《逸憩摄影》网站（包括我们的论坛）周三受到陌生黑客的攻击，这次事件令我们损失惨重。一方面，我们的一些注册会员账户信息丢失了，这些会员如果继续上传图片和在论坛发言，烦请重新注册一下；另一方面，网站上部分图片和贴子已遗失且无法恢复。在这里，我们向广大网友尤其是逸憩会员朋友们表示深深的歉意！\r\n\r\n    这次事件妥善处理之后，我们将一如既往的为广大摄影爱好者和模特们提供服务。希望各位网友继续支持我们的网站和工作室，真诚的感谢你们曾经对我们的支持！\r\n\r\n    这次不明黑客攻击我们的网站处于什么目的我们暂且不予公布，他们采取的手段非常恶劣，决非善意。我们对这种不道德的行为提出严厉指责并且保留用法律手段追究的权利。并且警告这次事件的策划者和实施者，多行不义必自毙！\r\n\r\n    最后我们要说明的是：《逸憩摄影》是一个非盈利性的网站，目的在于为广大摄影爱好者和模特提供交流的场所和个人相册服务。希望大家多多参与网站的管理和建设。我们希望听到各方面的呼声。\r\n\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2004-2-29 17:36:30编辑过][/color][/align]\r', '203.175.204.21', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (49, 132, 1057, 0, '', '一土文武', '帮你更清晰地了解自己的dc', 1078058700, '整理了一张图表《影像感应器尺寸规格》，帮你更清晰地了解自己的DC。胶片尺寸36*24，对于多数DC来讲，真是一个巨人！\r\nKODAK DCS Pro 14n CMOS 36*24\r\n\r\n[IMG]http://www.nphoto.net/forums/photos/gallery/531864324.jpg[/IMG]\r\n[IMG]http://www.nphoto.net/forums/photos/gallery/531864368.jpg[/IMG]\r\n[IMG]http://www.nphoto.net/forums/photos/gallery/531865266.jpg[/IMG]\r\n[IMG]http://www.nphoto.net/forums/photos/gallery/531868205.jpg[/IMG]\r\n\r\n转之新摄影！\r\n\r\n\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2004-2-29 20:46:23编辑过][/color][/align]\r', '218.0.12.71', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (49, 132, 1058, 0, '', 'ccong', '', 1078069860, '好资料！收藏：）', '221.136.112.4', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 133, 1059, 0, '', 'adan', '首届"中宁杯"摄影大赛于3月1日正式开拍[公告]', 1078119060, '首届"中宁杯"摄影大赛于3月1日正式开拍\r\n\r\n活动时间:2004.3.1--2004.3.10\r\n\r\n作品要求:以顶级写字楼"中宁大厦为主景\r\n附以"三江六岸"之美景\r\n塑造江景写字楼的自然合一\r\n\r\n奖项设置: 一等奖一名,奖人民币8000元\r\n二等奖二名,奖人民币4000元\r\n三等奖三名,奖人民币2000元\r\n特别奖若干名\r\n\r\n参赛标准: 参赛作品统一以8寸彩照为准\r\n参赛作品不得经过电脑特技处理;入选作品,须调底片审核\r\n主办单位拥有参赛作品今后使用之版权\r\n主办单位拥有对该摄影活动的最终解释权\r\n\r\n主办单位:宁波市摄影家协会 宁波市广兴房地产开发有限公司\r\n\r\n届时请广大摄影爱好者将作品寄往宁波市摄影家协会--"中宁杯"组委会\r\n\r\n宁波市摄影家协会地址:宁波市柳汀街150号\r\n中宁大厦地址:宁波市灵桥路255号\r\n咨询电话:0574-56113377\r\n\r\n\r\n', '210.83.124.138', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 134, 1060, 0, '', 'adan', '欢迎加入逸憩摄影同盟[公告]', 1078119720, '为方便色友联系以及我们逸憩活动信息的通知~\r\n我们建立了一个逸憩摄影同盟的 QQ群，群的号码是2852490\r\n\r\n欢迎大家加入~：）\r\n以后我们有什么活动信息将会在群里的一时间通知~：）\r\n\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2004-3-1 23:22:48编辑过][/color][/align]\r', '221.136.135.15', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (50, 78, 1061, 0, '', 'amurolay', '', 1078119840, '由上了一课了！', '218.0.4.249', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 135, 1062, 0, '', 'adan', '2004逸憩摄影大型风情外拍活动---春色西塘', 1078120740, '活动地点：西塘\r\n活动时间：3月13-14日\r\n活动费用：AA\r\n\r\n目前交通工具我们已经搞定~将有一位色友提供车辆~每位费用大概是250左右（包括来回的交通费和食宿费）\r\n\r\n本次活动目前报名色友名单：\r\n睁一只眼、老纳、ST0676、老僧、一土文武、摄色、刘姥姥、钉子、小蟹蟹、阿唐、游山游水、F15-C、佳子\r\n\r\n由于车位有限~原则上我们基本上不再接受报名~请下回赶早~HOHO\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n[align=right][color=#000066][此贴子已经被作者于2004-3-8 15:26:58编辑过][/color][/align]\r', '210.83.124.138', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (50, 78, 1063, 0, '', 'adan', '', 1078120920, '嘿嘿~以后有什么问题就在论坛里提出来好了~我们会安排在会所的交流活动中讲解的~：）', '210.83.124.138', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (49, 136, 1064, 0, '', 'adan', 'DC和DSLR到底你要谁？~[讨论]', 1078197780, '随着中国人民生活水平的提高~西西`数码影像产品越来越多的进入到我们的生活当中~~\r\n特别是去年开始数码单反放低架子也开始进入我们普通人的视野范围内~\r\n\r\n现在碰到一个问题~在选择数码相机的时候很多人往往在高级消费类数码相机（DC）和数码单反（DSLR）相机的选择之间产生困惑~~\r\n\r\n这样的困惑往往在以下几个机种中：\r\nDC：SONY F828、美能达A1，尼康5700\r\nDSLR：佳能EOS 300D、尼康D70、佳能EOS 10D、适马SD10\r\n\r\n\r\n不知道各位在这种进退两难的困惑中有何意见啊~HOHO~\r\n欢迎发表高见~~~：）\r\n\r\n\r\n\r\n\r\n\r', '210.83.124.138', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (49, 136, 1065, 0, '', '六月飞雪', '', 1078206600, '两个暂且不选,等明后年再说,坚持玩反转', '61.130.101.46', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (49, 136, 1066, 0, '', '一土文武', '', 1078240920, '偶现在是没什么期望的！渴望能若干年后能拥有1DS！\r\n梦想（不可能实现的叫梦想）－－－哈苏H1＋富士数码后背！呵呵！', '218.0.12.77', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (54, 137, 1067, 0, '', 'adan', '本周日李治国摄影作品专场观片会', 1078277940, '本周日（7号）下午2：00我们逸憩摄影将在会所夜色酒吧（原青鸟部落）举行宁波市摄影家协会会员李治国老师的专场幻灯片会，欢迎新老摄友们参加，一起聚聚，大家一起观片、学习、论片。\r\n\r\n\r\n酒吧位于鼓楼步行街主道的左手边，靠近中山广场', '210.83.124.138', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (53, 138, 1068, 0, '', '小丢', '新手～～到！3月3是女孩节哦', 1078312980, '新手来报道啦，不过这里看来好像蛮冷清哦\r\n我刚接触摄影没多久，嘿嘿，绝对菜鸟级，大家别见笑啊，多帮忙，谢了谢了～～\r\n\r\n今天是3月3日喔，女孩节哦，祝快乐快乐！！！', '218.0.1.163', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (50, 139, 1069, 0, '', '小丢', '问个很菜的问题啊', 1078314300, '问个很菜的问题啊\r\n我的中文版PHOTOSHOP里不知道怎么搞的，字体那里的全是英文的，害我不知道都是些什么字体，郁闷。请问要怎样把字体也汉化啊？是不是有字体汉化补丁？\r\n谢谢答疑~~/感动', '218.0.1.164', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (50, 139, 1070, 0, '', 'adan', '', 1078317420, '你的PS用的是什么版本？5.0还是6.0的？~', '221.136.133.223', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (53, 138, 1071, 0, '', 'adan', '', 1078317480, '女孩节？？还有这个节日吗？我怎么从来没听说过啊~哈哈\r\n欢迎MM加入色狼的队伍~HOHO', '221.136.133.223', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (50, 139, 1072, 0, '', 'qita', '', 1078322220, '这个网页里可能有你需要的汉化补丁! 你根据所安装的版本选一下吧,如果有所帮助就太好了.\r\nhttp://www.photoshopit.com/download/software.htm', '218.71.201.75', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (50, 139, 1073, 0, '', 'adan', '', 1078323600, '我想楼主说的只是中文字体的显示不是中文~不是整个PS软件的汉化~~\r\n这个问题是发生在PS5.0的版本中的~~好久没用了~不知道6.0是不是也会有这样的问题~反正7.0是没有的~\r\n\r\n楼主可以去找一下PS5.0的字体汉化插件工具~~我也忘记了~这个都比较老了~\r\n建议楼主安装PS7.0中文版~\r\nHOHO~我们网站里很多PS教程都是以PS7.0为运行环境的~HOHO~这样学起来也方便啊~：）', '221.136.133.223', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (53, 138, 1074, 0, '', '睁一只眼', '', 1078325700, '一起参加逸憩活动吧，不仅能够提高技术，还能够锻炼身体。哈哈！', '61.175.129.131', 1, 0, 0, 0, 0, 0);
