INSERT INTO `cdb_posts` VALUES (51, 140, 1078, 0, '', 'adan', 'SANDISK SD卡~128M~便宜卖了', 1078377180, '当移动存储用过一次~~过年前买的~一只也没用~~要的话350拿走吧~~\r\nQQ联系2396320\r\n一般都隐身~~留言好了~ \r\n', '210.83.124.138', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (50, 139, 1079, 0, '', 'adan', '', 1078389240, '那就奇怪了~我用的7.0都宋体隶书都是显示中文啊~没有安装其它字体插件啊~~\r\n你要不还个PS7.01的中文版本安装试试看~', '210.83.124.138', 1, 0, 0, 0, 0, 0);
