INSERT INTO `cdb_posts` VALUES (54, 143, 1097, 0, '', 'adan', '周三摄影技术交流教学活动[公告]', 1078711200, '逸憩摄影在周三晚上7点安排一次摄影技术的交流教学活动~其中包括PS教学，摄影技巧~摄影基础~作品点评~技术交流等内容。活动时间间隔基本上是两周一次～请大家注意～\r\n\r\n我们将经常邀请摄影界知名人士及高手现场教学~~大家也可以互相交流。\r\n\r\n活动地点在我们的会所(江东百丈路会展中心香辣居右邻“提克休闲酒吧")~\r\n\r\n每周三7点~欢迎所有爱好摄影的朋友参加~~我们的活动全部为免费~\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r', '221.136.135.254', 1, 0, 0, 0, 0, 0);
