INSERT INTO `cdb_posts` VALUES (55, 145, 1100, 0, '', '光的兴奋', '致站长：一个对本站的建议！', 1078721160, '站长：本站“上传图片”和“评论图片”的操作系统太烦杂！\r\n\r\n我敢下石：很多色友就因为这不想到这里来！我也是因为这个偶而才发PP！', '220.184.158.231', 1, 0, 0, 0, 0, 0);
