INSERT INTO `cdb_posts` VALUES (58, 315, 1251, 0, '', 'adan', '', 1095586320, 'HOHO~不好意思~服务器硬盘在更换中~所以有时候需要调试一下~最近如果出现暂时的无法观看或连接请稍安勿躁~明后天应该可以全部搞定了~以后会恢复正常的~\r\n', '221.136.135.83', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (58, 317, 1252, 0, '', '可心1825', '', 1095638160, '我已经下载了啊，我用的就是那些啊，为什么还是不行呢？？\r\n我去过帮助中心，好象我的问题那里没有的', '61.153.116.66', 1, 0, 0, 0, 0, 0);
INSERT INTO `cdb_posts` VALUES (58, 317, 1253, 0, '', 'adan', '', 1095641940, '这个应该是realone play的问题~\r\n我们网站上提供下载的realone play版本是2.0黄金版的~不是10.0的~\r\n你可以先下载2.0的安装~然后在打开realone play后选择菜单里的“工具”-“检查更新”里选择更新~然后联网更新升级为10.0的版本~应该就可以了~', '61.130.112.93', 1, 0, 0, 0, 0, 0);
