INSERT INTO `photo` VALUES (878, '凝固', 'Nikon', 'F80', '标头', '应该是柯达200吧', '', '', '9', '145862', 'Image-17.jpg', '2004-01-26 09:11:53', 134, '二子', '0', '0000-00-00 00:00:00', '北京五四纪念碑。拍摄时为正午，阳光非常强烈。所以阴影效果很差。照片放大过', '2004-09-23 17:02:09', 'IBHOU5YS3K9D4');
INSERT INTO `photo` VALUES (879, '人人都自恋', 'Nikon', 'F80', '70-300', '富士100', '', '', '1', '53344', 'Image-18.jpg', '2004-01-26 09:30:19', 263, '二子', '0', '0000-00-00 00:00:00', '给模特拍完之后还剩几张，于是就想自拍，靠，折腾半天累到死，最后拍成这幅德性。自拍真的很难', '2004-03-11 19:34:37', 'IBHOU5YS3K9D4');
INSERT INTO `photo` VALUES (880, '喜出望外阿', 'Nikon', 'F80', '标头', '柯达VS100', '', '', '3', '77815', 'Image-20.jpg', '2004-01-26 12:47:10', 57, '二子', '0', '0000-00-00 00:00:00', '天坛， \r\n端着相机，只想照那个洞洞，没想到窜下来一只小松鼠，吓了一跳，上天意外的赏赐，可惜，手抖了。小家伙一眨眼就钻洞里了。\r\n那一刻充分领略到摄影的乐趣，可是拿到拍虚了的PP真是懊恼了好久，懊恼到死啊', '2004-01-26 12:47:10', 'IBHOU5YS3K9D4');
INSERT INTO `photo` VALUES (2189, '渔归', 'Nikon', 'D100', '19-35/3.5-4.5', 'CCD', '', '', '5', '', '200412021646091216.jpg', '2004-12-02 16:46:10', 80, '月落西山', NULL, NULL, '在海边渔村买海鲜的时候发现了这一幕，就顾不得买鱼抓了一张！', NULL, 'WIVRV5LT3HY01');
