INSERT INTO `photo` VALUES (1647, '上海交大人像拍摄', 'Fujifilm', 's7000', 'fuji', 'CCD', '', '', '1', '127811', 'ok01.jpg', '2004-06-08 09:42:44', 411, 'cheney', '0', '0000-00-00 00:00:00', '模特：Halloween\r\n\r\n助理：ken dong\r\n\r\n感谢小白白友情介绍模特\r\n\r\n同样非常感谢模特MM，当时室外温度三十几度，非常的不容易\r\n\r\n拍摄地：上海交大徐汇校区\r\n\r\n【照规矩办　～ 勿评模特】\r\n\r\n第一次合作，我也紧张，模特也放不开，经过这次的磨合，相信已有默契\r\n\r\n已和MM约好，这礼拜再次合作：）\r\n', '2004-06-09 13:22:23', 'ISUCDOSTEMDCA');
