INSERT INTO `photo` VALUES (2051, 'COSPLAY照片', '其他品牌', 'CONTAX 645', '', 'AGFA', '', '', '1', '83949', 'k(7523)01.jpg', '2004-10-07 18:58:45', 205, '飘雪的天', '0', '0000-00-00 00:00:00', '相机 CONTAX 645     镜头 菜司 80/2  胶卷 AGFA 100反转  参数底片上有\r\n应邀参加杭州朋友的COSPLAY活动,顺便按了几下快门,主要是想体会镜头的感觉,拍得不好,大家凑和着看看效果吧\r\n前面四张是 海德堡分色扫描,最后张是数码冲印店扫描,可以比较下,适当PS下,尽量还原\r\n', '2004-10-08 10:41:41', 'UW5KCXOBIELTL');
