INSERT INTO `photo4` VALUES (886, '试机', '其他品牌', 'M6', 'LEICA35mm 2.0ASPH', 'Kodake 100VS', '', '', '4', '184290', '317067-Image1-embed.jpg', '2004-01-28 19:53:32', 61, '六月飞雪', '0', '0000-00-00 00:00:00', '趁着春节休假,用100VS拍了一卷，以供大家鉴赏。非常喜欢镜头的表现，不负莱卡的威望，果真有如传说中的那般，油！在家用上莱卡P300幻灯机，那种画面的表现的确是我CANON1V无法相比的。', '2004-01-29 09:48:47');
INSERT INTO `photo4` VALUES (887, '新年好', 'Canon', '1V', 'MACRO100mm', 'Kodake 100VS', '', '', '3', '137867', '317102-Image9-embed.jpg', '2004-01-28 20:27:38', 54, '六月飞雪', '0', '0000-00-00 00:00:00', '家里养的,用了U2灯.\r\n明天就要开工了,恭祝新的一年有新的收获!', '2004-02-07 18:19:14');
