INSERT INTO `photo4` VALUES (1598, '我住的地方', 'Canon', 'A75', '不知道', '也不知道', '', '', '6', '166585', 'full_small.jpg', '2004-05-22 22:25:11', 131, '无聊大头', '0', '0000-00-00 00:00:00', '这就是我住了两个月的鬼地方，左边那个小水塘子还不错，估计我走的时候要开满荷花了。正前方和右边是中航油的油罐，这段时间我一直希望它爆掉，那样我就可以早点回家了。想象还要在这呆上一个月就不爽。。。', '2004-05-23 19:14:46');
