INSERT INTO `photo4` VALUES (1944, '婚礼作品选登', 'Nikon', 'D100', '70-210/2.8  19-35/3.5-4.5', 'CCD', '', '', '1', '104309', 'x-1.jpg', '2004-08-17 15:34:48', 217, '月落西山', '0', '0000-00-00 00:00:00', '朋友的朋友结婚，让过去帮帮忙，后来就免费帮了一把，选几张片子，祝福他们~~~~', '2004-08-17 17:58:59');
INSERT INTO `photo4` VALUES (1946, '《如果这是叫幸福》', 'Minolta', 'ａ１', '', '', '', '', '2', '287873', 'PICT0013.jpg', '2004-08-18 13:07:44', 135, '爵士柠檬^o^', '0', '0000-00-00 00:00:00', '《如果这是叫幸福》 \r\n我闻到秋天的味道 \r\n那是坐在启程的火车上 \r\n望着窗外的风景，一片一片往后退 \r\n我知道了，自己正在途中…… \r\n忽然间，一阵暗涌 \r\n双眼红红的，是叫幸福吗？ \r\n不顾劳累地来往于爱情的途中，只为看他 \r\n如果这就是幸福 \r\n', '2004-08-19 08:55:58');
INSERT INTO `photo4` VALUES (1947, 'Dream Road', '未知品牌', '', '', '', '', '', '5', '77400', 'Road to my dreamtown2.jpg', '2004-08-18 19:09:50', 143, 'Ashebalano', '0', '0000-00-00 00:00:00', '初次来到这个网站,还望大家多包涵.照的是我的初中校园,用的是千方百计找同学借来的低档数码相机.', '2004-08-20 00:23:46');
