INSERT INTO `review` VALUES (50, 93, '老斯莱斯阿~哈哈~我又看到熟悉的602了~~偶的第一台DC就是602啊~~好怀念哦~~', 'adan', '2003-10-31 17:52:27', '221.136.187.138');
