INSERT INTO `review` VALUES (53, 93, '也是我的第一台！哈哈哈！我是菜鸟，还请多多指教啊。', '小蟹蟹', '2003-10-31 17:58:14', '221.136.111.93');
INSERT INTO `review` VALUES (54, 93, '我也是用602从菜鸟开始的~哈哈~我是去年12月底拿到602~开始了我的色影生涯~HOHO~<br>\n从一点不懂的菜鸟慢慢走到现在的~哈哈~只要用心学~多看多拍~一定可以成高手的~HOHO', 'adan', '2003-10-31 18:00:47', '221.136.187.138');
