INSERT INTO `review` VALUES (57, 88, '这个MM在上海读书的~你要不自己去找吧~娃哈哈~', 'adan', '2003-10-31 20:05:37', '221.136.187.138');
INSERT INTO `review` VALUES (58, 69, '有玻璃的质感，很好看', '睁一只眼', '2003-10-31 21:57:45', '61.174.161.151');
INSERT INTO `review` VALUES (59, 97, '传错了,怎么改啊', 'ahui', '2003-10-31 23:08:45', '221.136.162.8');
INSERT INTO `review` VALUES (60, 96, '数码作品后期应该处理下，最好能利用好光影的变化，角度认为要么再高点，要么就再低点', '飘雪的天', '2003-10-31 23:14:32', '218.0.121.104');
INSERT INTO `review` VALUES (61, 96, '如果主体是大桥的话还不够突出~~HOHO~<br>\n多看多拍吧~~：）', 'adan', '2003-10-31 23:23:42', '221.136.187.138');
INSERT INTO `review` VALUES (62, 97, '我来帮你改~', 'adan', '2003-10-31 23:24:00', '221.136.187.138');
INSERT INTO `review` VALUES (63, 96, '谁来帮俺处理一下,让俺看看处理的效果。另外，最好把图片改小,改成640的好,不要800的,发现上传了以后就不能改了！', 'ahui', '2003-10-31 23:35:34', '221.136.162.8');
INSERT INTO `review` VALUES (64, 83, '我猜一下好了~光圈值在6以上~曝光时间在2-4秒之间~HOHO', 'adan', '2003-10-31 23:55:32', '221.136.187.138');
INSERT INTO `review` VALUES (65, 100, '传错了,自己又不能改,都还没起来呢?', 'ahui', '2003-11-01 09:48:45', '221.136.162.8');
