INSERT INTO `review` VALUES (72, 110, '想起了小虎队的那首《红蜻蜓》~<br>\n真漂亮啊~', 'adan', '2003-11-01 20:33:30', '221.136.187.138');
INSERT INTO `review` VALUES (73, 108, '你PS的太过了~看看我们摄影技巧里的数码暗房吧~<br>\nHOHO~会对你有帮助的~', 'adan', '2003-11-01 20:39:45', '221.136.187.138');
