INSERT INTO `review` VALUES (76, 107, '要的就是这样的效果，不过快门还应该快点点，最好是上下抖动这样主体会清楚些', '飘雪的天', '2003-11-01 22:33:01', '218.71.195.245');
INSERT INTO `review` VALUES (77, 107, '娃哈哈~何止手抖啊~不过是故意的~虽然没有达到我预期的效果~不过这样也算是意外收获了~哈哈~猜猜看我是怎么拍的~', 'adan', '2003-11-01 22:36:50', '221.136.187.138');
INSERT INTO `review` VALUES (78, 123, '我来配音把~<br>\n青年：“小样儿，新来的吧？！”<br>\n娃哈哈~', 'adan', '2003-11-01 22:42:01', '221.136.187.138');
INSERT INTO `review` VALUES (79, 124, '我再来配音~<br>\n老大爷：“得儿，还是发扬风格，打不起，我，我还躲不起么我！”<br>\nHOHO', 'adan', '2003-11-01 22:46:18', '221.136.187.138');
INSERT INTO `review` VALUES (80, 125, '把模特拍得很到位。成熟，忧郁。', '睁一只眼', '2003-11-01 22:48:16', '218.74.232.195');
