INSERT INTO `review` VALUES (1275, 1124, '今天在奉化溪口的山路上远远望见那片黄。。。<br>\n大株大株的蕨类植物。。。<br>\n雪窦寺门外的石子路。。。和小庙。。。<br>\n在奉化棠云见到一坐当地人说是有500年历史的木桥。。。', '一土文武', '2004-03-03 20:51:06', '218.71.200.133');
