INSERT INTO `review` VALUES (1313, 1143, '晕死~你的扣图也用的太泛滥了吧~哈哈~~<br>\n不过这种扣图过度太明显了~破坏了画面~~PS还要多学习啊~HOHO', 'adan', '2004-03-06 22:58:53', '221.136.133.62');
