INSERT INTO `review` VALUES (1596, 1303, '哈哈~其实我的秘籍已经在网站的数码暗房里公开了呀~只是你们自己没有好好研究啊~HOHO<br>\n或者以后多参加我们逸憩会所的交流活动吧~会有PS教学的~：）', 'adan', '2004-03-30 23:21:38', '221.136.132.126');
