INSERT INTO `review` VALUES (1706, 1385, '也许我驽钝，看不出主题和照片之间的关联。<br>\n<br>\n不过片子效果很好。加油！', '睁一只眼', '2004-04-07 17:43:23', '203.175.204.21');
