INSERT INTO `review` VALUES (1721, 1331, '感觉还可以更亮点。对比加点', 'ccong', '2004-04-08 11:48:31', '221.136.112.171');
INSERT INTO `review` VALUES (1722, 1383, 'nnd！小谢谢观察的还真仔细！<br>\n经他一说确实连隐形眼镜都看得清楚啊！<br>\n又是一位大虾！高！！！', '多年以后', '2004-04-08 12:34:19', '221.136.52.160');
