INSERT INTO `review` VALUES (1724, 638, '对！照得真好，但是ps得很失败~~~~还可以看球那，一眼就知道是假得了', '月落西山', '2004-04-08 14:06:33', '61.179.111.146');
INSERT INTO `review` VALUES (1725, 1385, '高！就是高！<br>\n有深度，快赶上比加索了！hoho~~', '多年以后', '2004-04-08 23:30:58', '221.136.54.142');
INSERT INTO `review` VALUES (1726, 1366, '感觉不错，很有思想！', '多年以后', '2004-04-08 23:40:10', '221.136.54.142');
