INSERT INTO `review` VALUES (1732, 1385, '独自融化&nbsp;2004-4-9&nbsp;8:50:41&nbsp;&nbsp;头发?&nbsp;<br>\n<br>\n回头你看看我桌子小抽屉里就知道了！霍霍', 'ulike', '2004-04-09 16:36:57', '221.12.58.117');
