INSERT INTO `review` VALUES (1755, 1411, '说的真伤感，以后再在一起拍片、FB的时候会更开心的！！！哇哈哈哈', '小蟹蟹', '2004-04-13 08:49:47', '221.136.201.200');
INSERT INTO `review` VALUES (1756, 1411, '那天没来，只能说声遗憾了！常回来看看！', '飘雪的天', '2004-04-13 11:39:41', '221.12.58.115');
