INSERT INTO `review` VALUES (1758, 1411, '谢谢！你们真的是我的好兄弟！', '*摄色*', '2004-04-13 20:04:33', '218.73.0.118');
INSERT INTO `review` VALUES (1759, 1413, '应该靠近，靠近，再靠近。。。我们需要的是更大的震撼！<br>\n摄影当然是希望能挖掘出更深沉的东西来啊！<br>\n我们需要跟你一切靠近。。。', '一土文武', '2004-04-13 23:07:57', '218.0.13.65');
INSERT INTO `review` VALUES (1760, 1413, '历经生死沙场的人此时会有怎样的思绪，真是耐人寻味', '小蟹蟹', '2004-04-14 08:27:39', '221.136.201.44');
INSERT INTO `review` VALUES (1761, 1411, '我今年夏天去你家哦~哈哈~`<br>\n<br>\n', 'adan', '2004-04-14 13:23:36', '210.83.124.138');
INSERT INTO `review` VALUES (1762, 1411, '你来好了啊！一起去拍啊！', '*摄色*', '2004-04-14 15:37:17', '218.73.2.133');
INSERT INTO `review` VALUES (1763, 1413, '有深度！学习ING！', '*摄色*', '2004-04-14 15:53:16', '218.73.2.133');
INSERT INTO `review` VALUES (1764, 1415, '喷泉没仔细改过。看起来很难看。<br>\n回头改一下。<br>\n－－－－－－－－－新手上路请多关照。', '铃木阳一', '2004-04-14 18:31:00', '221.136.212.25');
INSERT INTO `review` VALUES (1765, 1415, '说句题外话，是中国人吗。。。为了照顾同胞的感情，请不要使用类似日本的名字。<br>\n<br>\n照片还是不错的', '睁一只眼', '2004-04-14 20:56:52', '61.174.164.126');
INSERT INTO `review` VALUES (1766, 1415, '强烈支持一只眼！！！看到这个名字就不舒服！', '多年以后', '2004-04-14 21:11:01', '221.136.48.129');
INSERT INTO `review` VALUES (1767, 1415, '555，其实我也很爱国的。<br>\n只是没办法。<br>\n以前取得名字就叫铃木阳一。<br>\n要是现在我也不会取的。<br>\n回头想个爱国的名字先……', '铃木阳一', '2004-04-14 21:11:26', '221.136.215.254');
INSERT INTO `review` VALUES (1768, 1415, '我不讨论名字～看片子能用A70拍出这样的片子效果的确不错～<br>\n曝光也基本准确～说明摄影基础知识是有了～不过美学方面可能还欠缺点～构图上基本上都太居中～这是摄影构图比较忌讳的一点～HOHO<br>\n<br>\n以后多看看别人的好片子～注意别人的构图～加油吧～HOHO', 'adan', '2004-04-14 21:34:15', '221.136.135.87');
INSERT INTO `review` VALUES (1769, 1418, '构图还可以，下面的杂草乱了些<br>\n<br>\n另外拍瀑布和流水的要诀，我记得上次木本老师说过，是：要达到一种似水非水、似石非石的效果，另外最好在阴天拍，小光圈，慢快门，用脚架。', 'ulike', '2004-04-14 22:29:22', '221.136.128.81');
INSERT INTO `review` VALUES (1770, 1414, '第一张有点乱哦~视觉中心没有了~', 'adan', '2004-04-15 09:29:09', '210.83.124.138');
INSERT INTO `review` VALUES (1771, 1425, '图片太大了～建议分辨路长宽不要超过600～<br>\n片子不错～看不出是A70拍的～HOHO', 'adan', '2004-04-15 22:10:05', '221.136.133.236');
INSERT INTO `review` VALUES (1772, 1182, 'nnd！高手就是高手！随便溜达都出好片，佩服佩服！', '多年以后', '2004-04-15 22:14:32', '221.136.55.238');
INSERT INTO `review` VALUES (1773, 1423, '好片子啊～是A70拍的马？不太像啊～HOHO', 'adan', '2004-04-15 22:16:31', '221.136.133.236');
INSERT INTO `review` VALUES (1774, 1425, '谢谢熊猫鼓励，hoho~~以后还请多多指教！！！', '多年以后', '2004-04-15 22:26:30', '221.136.55.238');
INSERT INTO `review` VALUES (1775, 1425, '？？？熊猫？不是说我吧～', 'adan', '2004-04-15 23:02:41', '221.136.133.236');
INSERT INTO `review` VALUES (1776, 1425, '你不熊猫谁熊猫！hoho~~~看你颠来倒去的闹的欢~~~挖哈哈', '多年以后', '2004-04-15 23:06:12', '221.136.55.238');
INSERT INTO `review` VALUES (1777, 1427, '小家伙不随波逐流好样的！hoho~~', '多年以后', '2004-04-17 11:55:20', '221.136.53.217');
INSERT INTO `review` VALUES (1778, 1428, '小孩子如此受人“尊重”啊', '睁一只眼', '2004-04-17 13:11:05', '61.174.164.126');
INSERT INTO `review` VALUES (1779, 1431, 'PS不漂亮，没有原味了！<br>\n少用特殊滤镜来使找票具有吸引力！', '*摄色*', '2004-04-17 21:56:41', '221.12.62.82');
INSERT INTO `review` VALUES (1780, 1433, '不错不错~~不过MM的眼睛看的不是地方~`<br>\n好象对焦也不是非常清楚~~HOHO~<br>\n构图创意各方面都挺好的', 'adan', '2004-04-17 22:00:19', '221.136.135.68');
INSERT INTO `review` VALUES (1781, 1434, '靠~胖子你的MM怎么那么漂亮啊<br>\n介绍我拍啊', '*摄色*', '2004-04-17 22:29:10', '221.12.62.82');
INSERT INTO `review` VALUES (1782, 1436, '磨皮过头了一点~西西~~', 'adan', '2004-04-17 22:44:57', '221.136.135.68');
INSERT INTO `review` VALUES (1783, 1437, '西西~磨皮也不能到处都磨啊~以后记得来会所上PS课吧~哈哈~<br>\n<br>\nPS技术还有待提高啊~西西~', 'adan', '2004-04-17 23:10:29', '221.136.135.68');
INSERT INTO `review` VALUES (1784, 1438, '关于“磨皮”，仁者见仁，智者见智。自己喜欢就按照自己的意愿<br>\n<br>\nadan并不代表全部的人像高手，也不代表顶尖人像高手。<br>\n<br>\n希望阿当看到我的评论不要吃醋噢，^_^', '睁一只眼', '2004-04-18 00:10:32', '61.174.164.126');
INSERT INTO `review` VALUES (1785, 1435, '图像处理给照片添色不少。', '睁一只眼', '2004-04-18 00:11:45', '61.174.164.126');
INSERT INTO `review` VALUES (1786, 1434, '我个人感觉还可以再生动些，色彩和对比可以再夸张些，味道才会出来。', '睁一只眼', '2004-04-18 00:12:50', '61.174.164.126');
INSERT INTO `review` VALUES (1787, 1434, '是啊是啊，拍的时候是阴天，草的颜色很闷，本来穿着亮色可以有很强的对比，但是灰了，胶片拍的好一点，可惜没扫描仪。还有小色，那个mm是别人带出来的啊，我也不熟啊！！！', 'linan', '2004-04-18 10:46:46', '221.136.215.22');
INSERT INTO `review` VALUES (1788, 1438, '娃哈哈~~言之有理~我说的仅仅是一家之言~可不要当作权威指导哦~<br>\n参考一下还是可以的~西西', 'adan', '2004-04-18 11:22:41', '221.136.132.220');
INSERT INTO `review` VALUES (1789, 1438, '各位大师又去拍mm了！不错不错！<br>\n熊猫亚当被扔鸡蛋了！好玩好玩！<br>\n宁波的天气这么热了！奇观奇怪！<br>\n', '多年以后', '2004-04-18 11:27:01', '221.136.49.232');
INSERT INTO `review` VALUES (1790, 1438, '铃木阳一&nbsp;?<br>\n是日本人？鄙视你，不用说理由了。<br>\n是中国人？更鄙视你，好好的取个日本名。', 'qlmzl', '2004-04-18 16:28:11', '220.184.73.132');
INSERT INTO `review` VALUES (1791, 1433, '好创意！！空间感强！如果将MODEL的姿势设计一下就好了。我的建议：MODEL正面贴着墙，与墙面纵深一致。或者蜷缩在柱子与墙之间。呵呵', '小蟹蟹', '2004-04-18 19:09:20', '221.136.200.6');
INSERT INTO `review` VALUES (1792, 1432, '色彩很清爽，但是有些虚啊', '小蟹蟹', '2004-04-18 19:10:54', '221.136.200.6');
INSERT INTO `review` VALUES (1793, 1439, '只能这么说..拍得挺好..可惜感觉模特没气质..最后一张还可以..但是感觉色调有点怪..', 'lsm', '2004-04-18 19:14:31', '217.43.210.112');
INSERT INTO `review` VALUES (1794, 1440, '很时尚的MM啊', '小蟹蟹', '2004-04-18 19:16:26', '221.136.200.6');
