INSERT INTO `review` VALUES (1797, 1439, 'lsm:你说错啦，模特很有气质，是我没拍好，最后一张的色调是一种尝试，呵呵', '小蟹蟹', '2004-04-18 19:19:19', '221.136.200.6');
