INSERT INTO `review` VALUES (1805, 1447, '螃蟹的DD拍的？<br>\n嗯。果然是螃蟹家族的。呵呵。<br>\n拍得不错。<br>\n我喜欢。', '铃木阳一', '2004-04-18 21:32:04', '221.136.214.131');
