INSERT INTO `review` VALUES (1967, 1570, '漂亮漂亮', '骏', '2004-05-17 20:47:09', '221.136.17.146');
INSERT INTO `review` VALUES (1968, 1570, '雨&nbsp;巷&nbsp;<br>\n<br>\n<br>\n<br>\n<br>\n<br>\n撑着油纸伞，独自<br>\n彷徨在悠长、悠长<br>\n又寂寥的雨巷，<br>\n我希望逢着<br>\n一个丁香一样地<br>\n结着愁怨的姑娘。<br>\n<br>\n她是有&nbsp;丁香一样的颜色，<br>\n丁香一样的芬芳，<br>\n丁香一样的忧愁，<br>\n在雨中哀怨，<br>\n哀怨又彷徨；<br>\n<br>\n她彷徨在这寂寥的雨巷，<br>\n撑着油纸伞<br>\n像我一样，<br>\n像我一样地<br>\n默默彳亍着，<br>\n冷漠，凄清，又惆怅。<br>\n<br>\n她默默地走近&nbsp;走近，又投出<br>\n太息一般的眼光<br>\n她飘过&nbsp;像梦一般地，<br>\n像梦一般地凄婉迷茫。<br>\n<br>\n像梦中飘过<br>\n一枝丁香地，<br>\n我身旁飘过这个女郎；<br>\n她静默地远了，远了，<br>\n到了颓圮的篱墙，<br>\n走尽这雨巷。<br>\n<br>\n在雨的哀曲里，<br>\n消了她的颜色，<br>\n消了她的芬芳，<br>\n消散了，甚至她的<br>\n太息般的眼光，<br>\n丁香般的惆怅。<br>\n<br>\n撑着油纸伞，独自<br>\n彷徨在悠长、悠长<br>\n又寂寥的雨巷，<br>\n我希望飘过<br>\n一个丁香一样地<br>\n结着愁怨的姑娘。&nbsp;<br>\n', '宁芙2004', '2004-05-18 08:35:33', '221.136.192.55');
