INSERT INTO `review` VALUES (2071, 1633, '赫赫，阿当果然眼光犀利！<br>\n<br>\n基本上是，可惜还没学到家&nbsp;：（<br>\n<br>\n1.复制图层<br>\n<br>\n2.柔光<br>\n<br>\n3.拷贝绿通道<br>\n<br>\n4.正片叠底<br>\n<br>\n5.微调', 'ulike', '2004-05-31 15:46:31', '221.12.58.117');
