INSERT INTO `review` VALUES (2075, 1628, '感谢睁一只眼的鼓励,<br>\n尽管水平不行，<br>\n却发现慢慢地越来越喜欢摄影，<br>\n<br>\n有时候，摄影可以带给一个人很多快乐，<br>\n有时候，摄影可以让人忘掉很多东西...<br>\n<br>\n虽然这些只是一组普通的抓拍,<br>\n但是有人鼓励，真的很高兴!<br>\n<br>\n也希望,有更多的朋友喜欢摄影,来到17camera<br>\n<br>\n', 'ahui', '2004-05-31 21:44:27', '221.136.150.215');
INSERT INTO `review` VALUES (2076, 1628, '西西~ahui进步很快啊~<br>\n相信不久也能成为一位老色手了~哈哈~<br>\n有空多来17发片~大家互相切磋提高技艺~：）', 'adan', '2004-05-31 23:23:53', '221.136.135.199');
