INSERT INTO `review` VALUES (2175, 1679, '乍一看～我还以为小DD没穿裤子呢～HOHO', 'adan', '2004-06-14 11:01:28', '61.130.112.93');
INSERT INTO `review` VALUES (2176, 1672, '交关PL', 'road', '2004-06-14 11:16:28', '61.174.161.212');
INSERT INTO `review` VALUES (2177, 1676, '拍的有想法<br>\nMM好……', 'road', '2004-06-14 11:17:39', '61.174.161.212');
INSERT INTO `review` VALUES (2178, 1679, '小DD在海边跑&nbsp;没穿裤子也很正常啊&nbsp;&nbsp;<br>\n娃哈哈', 'cheney', '2004-06-14 11:23:18', '218.80.208.39');
INSERT INTO `review` VALUES (2179, 51, '片子好漂亮,是什么时间拍的?清晨?<br>\n只是上面的小黑点有点肉麻~~~~', '青和', '2004-06-14 11:24:50', '218.108.40.99');
INSERT INTO `review` VALUES (2180, 1680, '就一张阿？太不过瘾了～<br>\n别都藏着呀｀嘿嘿', 'adan', '2004-06-14 13:03:30', '61.130.112.93');
INSERT INTO `review` VALUES (2181, 1659, '创意不错，但是我总觉得构图和焦点如何处理会更好', '老古董', '2004-06-14 14:28:28', '61.175.235.185');
INSERT INTO `review` VALUES (2182, 1643, '黑白不错的意境，但是后面几张我觉得比较散乱', '老古董', '2004-06-14 14:29:25', '61.175.235.185');
INSERT INTO `review` VALUES (2183, 1115, '色调不错，但是我觉得旁边有些乱', '老古董', '2004-06-14 14:31:11', '61.175.235.185');
INSERT INTO `review` VALUES (2184, 1401, '世态的扭曲？生活的无奈？', '老古董', '2004-06-14 14:32:08', '61.175.235.185');
INSERT INTO `review` VALUES (2185, 1524, '完美结合我喜欢', '老古董', '2004-06-14 14:32:44', '61.175.235.185');
INSERT INTO `review` VALUES (2186, 1680, '很不错，但是觉得线条多了些不然很完美', '老古董', '2004-06-14 14:34:09', '61.175.235.185');
INSERT INTO `review` VALUES (2187, 1681, '第一张如果背景能暗些就好啦，烟头这边就会更加突出一些，呵呵', '小蟹蟹', '2004-06-14 16:57:48', '203.175.235.123');
INSERT INTO `review` VALUES (2188, 1680, '牛啊！强烈的光线、浓重的阴影，给人一种燥热的感觉，主题很突出！！不过如果是我，我会把MM头顶上电线以上部分裁掉，首先头顶上的竹竿有些枪眼，可以去掉了；其次，页面呈宽幅，视觉效果不错。呵呵', '小蟹蟹', '2004-06-14 17:12:08', '203.175.235.123');
INSERT INTO `review` VALUES (2189, 1681, '还有：这种类型的图片用噪点的效果更爽！哈哈', '小蟹蟹', '2004-06-14 17:14:31', '203.175.235.123');
INSERT INTO `review` VALUES (2190, 1681, '晕死~~螃蟹又在放毒勒~<br>\n<br>\n比较小资的作品～我刚学摄影的时候也玩过～哈哈哈～<br>\n不错不错～', 'adan', '2004-06-14 17:27:41', '61.130.112.93');
INSERT INTO `review` VALUES (2191, 1681, '谢谢各位前辈大师们的指教!', '亚情', '2004-06-14 18:13:11', '221.136.21.65');
INSERT INTO `review` VALUES (2192, 1681, '咋一看以为又是小蟹蟹的作品，<br>\n和蟹蟹的风格很象~~', '多年以后', '2004-06-14 18:58:11', '221.136.55.121');
INSERT INTO `review` VALUES (2193, 1490, '请问一下飘雪,这种静物怎么用光的???上面的照片上,光源有几个???<br>\n是从哪个方向打光过来的?????', '亚情', '2004-06-14 19:39:37', '221.136.21.65');
INSERT INTO `review` VALUES (2194, 1025, '请问一下飘雪,这种静物怎么用光的???上面的照片上,光源有几个???<br>\n是从哪个方向打光过来的?????&nbsp;<br>\n', '亚情', '2004-06-14 19:40:21', '221.136.21.65');
INSERT INTO `review` VALUES (2195, 1682, '这是补的两张,adan，能否帮我把这两张和前面那两张归到一起，感谢！', 'ahui', '2004-06-14 20:16:46', '221.136.149.103');
INSERT INTO `review` VALUES (2196, 1683, '搞定拉~哈哈', 'adan', '2004-06-14 22:00:40', '221.136.133.116');
INSERT INTO `review` VALUES (2197, 51, '拍摄时间大概是早上8点半左右~花上黑黑的可能是虫卵~西西', 'adan', '2004-06-14 22:55:35', '221.136.133.116');
INSERT INTO `review` VALUES (2198, 1524, '和和，謝謝欣賞，近期還有些作品會發上來希望到時候大家來評判', '小猪猪', '2004-06-14 23:03:36', '221.136.149.194');
INSERT INTO `review` VALUES (2199, 1685, '磨皮好象过度还是高斯模糊太过了，脸毛绒绒的。', '多年以后', '2004-06-15 12:15:04', '221.136.54.127');
INSERT INTO `review` VALUES (2200, 1685, '看明白了，原来是在模拟进深呀，难怪。', '多年以后', '2004-06-15 12:16:40', '221.136.54.127');
INSERT INTO `review` VALUES (2201, 1681, '觉得主题很好&nbsp;能使人产生共鸣', '第三只眼', '2004-06-15 19:24:38', '218.0.3.254');
INSERT INTO `review` VALUES (2202, 1680, '表现力很强。我觉得电线和竹竿去掉是一种感觉，不去掉又是另一种感觉。没有电线和竹竿会有种空灵的感觉，而保留这些就给人物赋予某种情绪，一些不安和冲动。', 'st0676', '2004-06-15 22:05:59', '218.74.232.216');
INSERT INTO `review` VALUES (2203, 1681, '第一张东西的位置不好，最好再随意点。<br>\n第二张左下太重了。<br>\n', 'st0676', '2004-06-15 22:17:36', '218.74.232.216');
INSERT INTO `review` VALUES (2204, 1687, '怎么上传图片,老是叫我重命名啊,我没用中文啊,管理员来看看啦', '亚情', '2004-06-16 15:01:39', '221.136.19.128');
INSERT INTO `review` VALUES (2205, 1182, '摄影家眼里的景色,的确与众不同!!欣赏!!!&nbsp;能不能也做成桌面以供大家长久地赏悦?&nbsp;谢谢!~', 'qita', '2004-06-16 23:19:01', '218.74.235.251');
INSERT INTO `review` VALUES (2206, 1689, 'PS想法不错~不过锐化过了一点点，磨皮过了一点点，PS过了一点点~西西~<br>\n以后多加油哦~', 'adan', '2004-06-16 23:53:54', '221.136.134.215');
INSERT INTO `review` VALUES (2207, 1690, '总体都不错~不过第一张虽然是对角线构图但是还是觉得有点倒了~<br>\n第二张我不太清楚是作者故意对焦在荷叶上还是跑焦了跑到荷叶上了~西西', 'adan', '2004-06-16 23:55:49', '221.136.134.215');
INSERT INTO `review` VALUES (2208, 1684, '恐怖', '月落西山', '2004-06-17 08:02:19', '61.179.111.146');
INSERT INTO `review` VALUES (2209, 1691, '还有一张横幅，上不了了！！拍这些玩意没有广角是件郁闷的事', '月落西山', '2004-06-17 08:09:22', '61.179.111.146');
INSERT INTO `review` VALUES (2210, 1691, '这组图片越看越精彩！！喜欢第5幅', '小蟹蟹', '2004-06-17 08:28:36', '203.175.237.103');
INSERT INTO `review` VALUES (2211, 1690, '你是说第一张是不是构图上有些不稳?<br>\n第二张对焦是个头痛的问题,正想请教呢,不知为何,我一对焦就自动跑到前面的物体上了,不知怎么解决?', '青和', '2004-06-17 10:40:42', '218.108.40.99');
INSERT INTO `review` VALUES (2212, 1693, '不错，不错真不错！丢丢已经有点自己独特风格了！', '多年以后', '2004-06-17 22:21:50', '221.136.55.239');
INSERT INTO `review` VALUES (2213, 1693, '构图非常有自己的想法<br>\n<br>\n还需注意构图边缘细节上的裁切<br>\n<br>\n整体风格不错', 'cheney', '2004-06-17 22:26:01', '221.137.0.139');
INSERT INTO `review` VALUES (2214, 1693, '边缘细节的裁切？能给我举例说下吗？HOHO～～，谢谢指点', '小丢@', '2004-06-18 12:38:23', '218.0.1.166');
INSERT INTO `review` VALUES (2215, 1693, '呵呵，多谢多年的夸奖，哈哈，飘飘然了。<br>\n不过实在不敢当，不过自己正在努力中～希望自己能有自己的风格，希望自己能拍出好片……', '小丢@', '2004-06-18 12:45:32', '218.0.1.164');
INSERT INTO `review` VALUES (2216, 1695, '曝光欠了一点～层次感不够强阿～', 'adan', '2004-06-18 13:57:24', '61.130.112.93');
INSERT INTO `review` VALUES (2217, 1696, '按错了投票，在飞机上拍的，哈哈天气不错啊', 'linan', '2004-06-18 15:16:13', '61.175.132.10');
INSERT INTO `review` VALUES (2218, 1694, '脸皮确实够厚，偶就是太害羞了，人多不好意思带脚架。<br>\n什么时候带偶也去练练脸皮~~呵呵~~<br>\n拍的真不错！哦也！', '多年以后', '2004-06-18 18:07:13', '221.136.54.34');
INSERT INTO `review` VALUES (2219, 1440, '我借你一把菜刀！ADAN', '月落西山', '2004-06-19 09:53:07', '61.179.111.146');
