INSERT INTO `review` VALUES (2221, 1699, '可改变下白平衡，使夕阳更加红一点，是一般的美学观点。', 'dominic12345', '2004-06-19 21:36:26', '218.0.7.175');
INSERT INTO `review` VALUES (2222, 1706, '其他都不错，就是最后一张广角用的不是很好', '*摄色*', '2004-06-20 18:11:46', '218.109.222.140');
