INSERT INTO `review` VALUES (2655, 2031, 'HOHO~出去玩啦~<br>\n有几张过曝了~还有几张构图太空~：P<br>\n一定没有听过以前木本老师讲课~', 'adan', '2004-09-26 14:21:42', '221.136.133.36');
INSERT INTO `review` VALUES (2656, 2030, '搜标题佛啊~~哈哈哈~<br>\n我想如果用黑卡把下面暗部细节都表现出来的话会更精彩~', 'adan', '2004-09-26 14:22:37', '221.136.133.36');
INSERT INTO `review` VALUES (2657, 2031, ':(没听~', 'mi', '2004-09-26 16:59:47', '61.153.140.62');
INSERT INTO `review` VALUES (2658, 2034, '花里胡哨是什么虫虫？~', 'adan', '2004-09-26 17:08:32', '221.136.133.36');
INSERT INTO `review` VALUES (2659, 2034, '这张照片引起我胃部不适.......', 'Ashebalano', '2004-09-26 17:18:10', '221.233.35.188');
INSERT INTO `review` VALUES (2660, 556, '暴光是过了~<br>\n夜景的片子暴光一旦失误就什么都不用说了~~<br>\n重拍吧~<br>\n还有就是车灯的轨迹没有控制好~~<br>\n片子发灰~~我不知道是扫描的原因还是因为杂光的关系~~<br>\n最后就是光圈~~<br>\n我宁可使用中灰滤镜压暗光线延长暴光时间~~<br>\n一般不会把光圈开太小~~<br>\n因为光圈太小后引起的星光的效果让人眼晕~~或者说是太多的星光让画面杂乱~~<br>\n', '瓦西里', '2004-09-26 19:24:58', '219.82.206.30');
INSERT INTO `review` VALUES (2661, 2034, '没对好焦', '瓦西里', '2004-09-26 19:26:25', '219.82.206.30');
INSERT INTO `review` VALUES (2662, 2032, '恩~~刚转行-还在摸呢~~~以前是死不拍女人的~~<br>\n这段时间会陆续的弄点片子上来~~<br>\nADAN到时候关照一下啊~有什么问题多指教~<br>\n~还有哪个网站里《&nbsp;异形总动员》我死活看不了~~怎么回事啊~？', '瓦西里', '2004-09-26 19:30:24', '219.82.206.30');
INSERT INTO `review` VALUES (2663, 2032, '哈哈&nbsp;~大家以后一起切磋啊~<br>\n那个异形总动员已经搞定了~可以看了~HOHO~', 'adan', '2004-09-26 19:49:51', '221.136.133.36');
INSERT INTO `review` VALUES (2664, 2035, '感觉模特有点僵啊~`HOHO', 'adan', '2004-09-26 20:15:32', '221.136.133.36');
INSERT INTO `review` VALUES (2665, 2035, '恩~~那哥们放不开~~以前没有拍过着种照片~~<br>\n我也是~~~~~', '瓦西里', '2004-09-26 20:40:25', '219.82.206.30');
INSERT INTO `review` VALUES (2666, 2035, '绝对的标准人像！', '小蟹蟹', '2004-09-27 07:51:11', '203.175.232.129');
INSERT INTO `review` VALUES (2667, 1659, '背景太虚了', '一米线', '2004-09-27 16:20:27', '218.71.239.154');
INSERT INTO `review` VALUES (2668, 2037, 'HOHO~怎么不帮MM磨磨皮阿~', 'adan', '2004-09-27 18:05:52', '221.136.135.43');
INSERT INTO `review` VALUES (2669, 2037, '差不多是全发上来了~<br>\n这个不是我的创作~~<br>\n我道行还不够~~创作轮不到我~~<br>\n就是我一个当记者的朋友买了几件新衣服想我拍几张做个纪念~<br>\n无奈她的皮肤状态实在不是很好~~<br>\n所以特写部分几乎就是没有~~<br>\n前面2里面蟹蟹说的对~~就是称做标准人像~~<br>\n换句话说就是没有什么创意~~中轨中矩~~甚至是比较死板的东西~~<br>\n哈哈~~<br>\n我同意~~~<br>\n我在拍摄的时候和MT是一样紧张的~~我们都是新手~~<br>\n我是最近刚开始拍人~~<br>\n现在是不求有功~~但求无过~~~<br>\n不过我还是顺手按照自己的思路拍了点东西~~<br>\n权当实验吧~~<br>\n', '瓦西里', '2004-09-27 18:09:40', '219.82.196.176');
INSERT INTO `review` VALUES (2670, 2037, '后面几张是我留给自己的~<br>\n我自己的东西从来就不磨的说~~<br>\n哈哈～～<br>\n顺便让大家知道为什么几乎没有拍半身和特写～～呵呵~~<br>\n实在是不敢~~~', '瓦西里', '2004-09-27 18:11:51', '219.82.196.176');
INSERT INTO `review` VALUES (2671, 1796, '这是济南的五龙潭吗？我比较喜欢第2张，水象雾一样。', 'dingdingjn', '2004-09-27 22:13:53', '60.232.0.73');
